<template><view class="page"><view class="identity"><view class="avatar">{{demoStore.user.name.slice(0,1)}}</view><view><view class="name">{{demoStore.user.name}}</view><view class="sub">{{demoStore.user.department}} · {{roleNames[demoStore.role]}}</view></view></view><view class="section"><view class="section-title">工作入口</view><view class="entry" @click="open('/pages/messages/index')"><view><view class="entry-name">消息中心</view><view class="sub">临期、逾期、交办与闭环提醒</view></view><view>›</view></view><view v-if="demoStore.can('issue-list')" class="entry" @click="open('/pages/issue/list')"><view><view class="entry-name">整改单</view><view class="sub">按权限处理隐患交办与整改</view></view><view>›</view></view><view v-if="demoStore.can('duty-overview')" class="entry" @click="open('/pages/admin/duty')"><view><view class="entry-name">安全履职总览</view><view class="sub">筛选人员、部门、周期和完成状态</view></view><view>›</view></view><view v-if="demoStore.can('admin')" class="entry" @click="open('/pages/admin/inspection')"><view><view class="entry-name">安监抽查</view><view class="sub">真实情况抽查与关联整改</view></view><view>›</view></view><view v-if="demoStore.can('admin')" class="entry" @click="open('/pages/admin/templates')"><view><view class="entry-name">检查表模板</view><view class="sub">管理未来任务，历史任务不会被覆盖</view></view><view>›</view></view></view><view class="section"><view class="section-title">切换演示身份</view><view v-for="item in allRoles" :key="item.id" class="role" :class="{active:item.id===demoStore.role}" @click="demoStore.setRole(item.id)"><view><view class="entry-name">{{item.roleName}}</view><view class="sub">{{item.department}} · {{item.name}}</view></view><view class="check">{{item.id===demoStore.role?'✓':''}}</view></view></view><view class="section guide"><view class="section-title">生产版权限边界</view><view>整改单由服务端再次校验角色、部门和任务归属。员工履职按本人真实周期读取和提交；现场照片、AI 审核、账号密码均不保存在小程序端。</view></view><button class="logout" @click="logout">返回登录页</button></view></template>
<script setup>import {allRoles,demoStore,roleNames} from '../../stores/demo';function open(url){uni.navigateTo({url})}function logout(){demoStore.logout();uni.navigateTo({url:'/pages/auth/login'})}</script>
<style lang="scss" scoped>.page{padding:32rpx 28rpx 64rpx;max-width:960px;margin:auto}.identity{display:flex;align-items:center;gap:18rpx;margin:12rpx 0 34rpx}.avatar{width:86rpx;height:86rpx;display:flex;align-items:center;justify-content:center;background:#211d1d;color:#fff;border-radius:22rpx 22rpx 22rpx 5rpx;font-size:39rpx;font-weight:700}.name{font-size:35rpx;font-weight:750}.sub,.guide{font-size:22rpx;color:#756c6b;line-height:1.6;margin-top:4rpx}.section{background:#fffcfa;border-radius:20rpx;padding:26rpx;margin-bottom:18rpx}.section-title{font-size:29rpx;font-weight:730;margin-bottom:10rpx}.entry,.role{display:flex;align-items:center;justify-content:space-between;padding:19rpx 0;border-top:1rpx solid #eee6e3;font-size:32rpx}.entry-name{font-size:26rpx;font-weight:650}.role.active .entry-name{color:#9f2349}.check{width:36rpx;height:36rpx;border-radius:50%;background:#eee8e5;color:#9f2349;text-align:center;line-height:36rpx;font-size:22rpx}.active .check{background:#9f2349;color:#fff}.guide{margin:0}.logout{background:#eee8e5;color:#514946;border-radius:12rpx;font-size:25rpx}@media(min-width:900px){.page{padding:28px 30px 56px}.identity{gap:14px;margin:10px 0 30px}.avatar{width:60px;height:60px;font-size:25px;border-radius:18px 18px 18px 4px}.name{font-size:25px}.sub,.guide{font-size:13px}.section{border-radius:16px;padding:22px;margin-bottom:14px}.section-title{font-size:18px}.entry,.role{padding:15px 0;font-size:20px}.entry-name{font-size:15px}.check{width:24px;height:24px;line-height:24px;font-size:14px}.logout{font-size:14px}}</style>
